#!/usr/bin/env bash
# Compares a built engine against the golden outputs generated by the reference binary.
#
#   bash scripts/check-golden.sh dist/vaulttool-linux-x86_64
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
BIN="${1:-$ROOT/dist/vaulttool-linux-x86_64}"
GOLDEN="$ROOT/golden"
SEED=-7346913998703726680
FAILED=0

case "$BIN" in
    /*) ;;
    *) BIN="$(pwd)/$BIN" ;;
esac

if [ ! -x "$BIN" ]; then
    echo "engine not found or not executable: $BIN" >&2
    exit 1
fi

WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT

check() {
    local name="$1"
    sed 's/\r$//' "$WORK/$name" >"$WORK/$name.norm"
    sed 's/\r$//' "$GOLDEN/$name" >"$WORK/$name.gold"
    if diff -u "$WORK/$name.gold" "$WORK/$name.norm" >"$WORK/$name.diff"; then
        echo "ok   $name"
    else
        echo "FAIL $name"
        sed -n '1,20p' "$WORK/$name.diff"
        FAILED=1
    fi
}

itemspec_of_line() {
    awk -v line="$1" 'NR == line {
        sub(/^[^ ]+ [0-9]+ ITEMS [0-9]+ /, "");
        print
    }' "$GOLDEN/pred-ominous-A.txt"
}

SPEC4="$(itemspec_of_line 4)"
SPEC7="$(itemspec_of_line 7)"

cd "$WORK"
"$BIN" pred "$SEED" 1 0 10 >pred-ominous-A.txt
check pred-ominous-A.txt
"$BIN" pred "$SEED" 0 0 10 >pred-normal-A.txt
check pred-normal-A.txt
"$BIN" pred 0 1 0 10 >pred-ominous-0.txt
check pred-ominous-0.txt
"$BIN" pred 12345 1 0 10 >pred-ominous-12345.txt
check pred-ominous-12345.txt
"$BIN" matches "$SEED" 1 2000000 "$SPEC4" >matches-2M.txt
check matches-2M.txt
awk '/^M / {print $2; count++} count == 200 {exit}' "$GOLDEN/matches-2M.txt" >cands-200.txt
"$BIN" narrow "$SEED" 1 4 100 30 "$SPEC7" cands-200.txt >narrow.txt
check narrow.txt
"$BIN" detect "$SEED" 1 0 2000 "$SPEC4" >detect.txt
check detect.txt
"$BIN" search "$SEED" 1 0 100000 5 'minecraft:enchanted_golden_apple;minecraft:heavy_core' >search.txt
check search.txt

if [ "$FAILED" -ne 0 ]; then
    echo "golden comparison failed" >&2
    exit 1
fi
echo "golden comparison passed"
